/// Returns an index of a minimal element in the suffix `a[lo..]`.
/// 
/// Preconditions (as stated in the problem):
/// - `a.len() > 0`
/// - `lo < a.len()`
pub fn find_min(a: &[i32], lo: usize) -> usize {
    debug_assert!(!a.is_empty(), "precondition violated: array must be non-empty");
    debug_assert!(lo < a.len(), "precondition violated: lo out of bounds");

    let mut min_idx = lo;
    let mut min_val = a[lo];

    for i in (lo + 1)..a.len() {
        let v = a[i];
        if v < min_val {
            min_val = v;
            min_idx = i;
        }
    }

    min_idx
}